func NewCftValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) CftValue {
	object, diags := NewCftValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewCftValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t CftType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewCftValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewCftValueUnknown(), nil
	}

	if in.IsNull() {
		return NewCftValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewCftValueMust(CftValue{}.AttributeTypes(ctx), attributes), nil
}

func (t CftType) ValueType(ctx context.Context) attr.Value {
	return CftValue{}
}

type CftValue struct {
	Description           basetypes.StringValue `tfsdk:"description"`
	Id                    basetypes.Int64Value  `tfsdk:"id"`
	Name                  basetypes.StringValue `tfsdk:"name"`
	Policy                basetypes.StringValue `tfsdk:"policy"`
	Region                basetypes.StringValue `tfsdk:"region"`
	Regions               basetypes.ListValue   `tfsdk:"regions"`
	SnsArns               basetypes.StringValue `tfsdk:"sns_arns"`
	SystemManaged         basetypes.BoolValue   `tfsdk:"system_managed"`
	TemplateParameters    basetypes.StringValue `tfsdk:"template_parameters"`
	TerminationProtection basetypes.BoolValue   `tfsdk:"termination_protection"`
	state                 attr.ValueState
}

func (v CftValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 10)

	var val tftypes.Value
	var err error

	attrTypes["description"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["id"] = basetypes.Int64Type{}.TerraformType(ctx)
	attrTypes["name"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["policy"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["region"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["regions"] = basetypes.ListType{
		ElemType: types.StringType,
	}.TerraformType(ctx)
	attrTypes["sns_arns"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["system_managed"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["template_parameters"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["termination_protection"] = basetypes.BoolType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 10)

		val, err = v.Description.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["description"] = val

		val, err = v.Id.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["id"] = val

		val, err = v.Name.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["name"] = val

		val, err = v.Policy.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["policy"] = val

		val, err = v.Region.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["region"] = val

		val, err = v.Regions.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["regions"] = val

		val, err = v.SnsArns.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["sns_arns"] = val

		val, err = v.SystemManaged.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["system_managed"] = val

		val, err = v.TemplateParameters.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["template_parameters"] = val

		val, err = v.TerminationProtection.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["termination_protection"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v CftValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v CftValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v CftValue) String() string {
	return "CftValue"
}

func (v CftValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var regionsVal basetypes.ListValue
	switch {
	case v.Regions.IsUnknown():
		regionsVal = types.ListUnknown(types.StringType)
	case v.Regions.IsNull():
		regionsVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		regionsVal, d = types.ListValue(types.StringType, v.Regions.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"description": basetypes.StringType{},
			"id":          basetypes.Int64Type{},
			"name":        basetypes.StringType{},
			"policy":      basetypes.StringType{},
			"region":      basetypes.StringType{},
			"regions": basetypes.ListType{
				ElemType: types.StringType,
			},
			"sns_arns":               basetypes.StringType{},
			"system_managed":         basetypes.BoolType{},
			"template_parameters":    basetypes.StringType{},
			"termination_protection": basetypes.BoolType{},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"description": basetypes.StringType{},
		"id":          basetypes.Int64Type{},
		"name":        basetypes.StringType{},
		"policy":      basetypes.StringType{},
		"region":      basetypes.StringType{},
		"regions": basetypes.ListType{
			ElemType: types.StringType,
		},
		"sns_arns":               basetypes.StringType{},
		"system_managed":         basetypes.BoolType{},
		"template_parameters":    basetypes.StringType{},
		"termination_protection": basetypes.BoolType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"description":            v.Description,
			"id":                     v.Id,
			"name":                   v.Name,
			"policy":                 v.Policy,
			"region":                 v.Region,
			"regions":                regionsVal,
			"sns_arns":               v.SnsArns,
			"system_managed":         v.SystemManaged,
			"template_parameters":    v.TemplateParameters,
			"termination_protection": v.TerminationProtection,
		})

	return objVal, diags
}

func (v CftValue) Equal(o attr.Value) bool {
	other, ok := o.(CftValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Description.Equal(other.Description) {
		return false
	}

	if !v.Id.Equal(other.Id) {
		return false
	}

	if !v.Name.Equal(other.Name) {
		return false
	}

	if !v.Policy.Equal(other.Policy) {
		return false
	}

	if !v.Region.Equal(other.Region) {
		return false
	}

	if !v.Regions.Equal(other.Regions) {
		return false
	}

	if !v.SnsArns.Equal(other.SnsArns) {
		return false
	}

	if !v.SystemManaged.Equal(other.SystemManaged) {
		return false
	}

	if !v.TemplateParameters.Equal(other.TemplateParameters) {
		return false
	}

	if !v.TerminationProtection.Equal(other.TerminationProtection) {
		return false
	}

	return true
}

